#include <stdio.h>

int main(void) {
    int n = 5;
    int old = n++;
    int now = ++n;
    printf("%d %d %d\n", old, now, n);
    return 0;
}

#include <stdio.h>

int main(void) {
    int total = 10;
    total += 5;
    total *= 2;
    printf("%d\n", total);
    return 0;
}

#include <stdio.h>

int main(void) {
    int score = 60;
    printf("%d %d\n", score >= 60, score == 100);
    return 0;
}

#include <stdio.h>

int main(void) {
    int score = 85;
    printf("%d\n", score >= 0 && score <= 100);
    return 0;
}

#include <stdio.h>

int main(void) {
    int day = 7;
    printf("%d\n", day == 6 || day == 7);
    return 0;
}

#include <stdio.h>

int main(void) {
    int score = 120;
    printf("%d %d\n", !(score >= 0 && score <= 100), !!score);
    return 0;
}

#include <stdio.h>
#include <stdbool.h>

int main(void) {
    int n = 8;
    bool valid = n >= 0 && n % 2 == 0;
    printf("%d\n", valid);
    return 0;
}
